const fs = require('fs');
const buf = fs.readFileSync('/workspace/world.db');
const str = buf.toString('utf8');
// Search for larger context around the onboarding email
const idx = str.indexOf('High Priority: Onboarding Equipment Setup Needed.eml');
if (idx > -1) {
  // Get a wide window around this
  const start = Math.max(0, idx - 200);
  const end = Math.min(str.length, idx + 2000);
  const chunk = str.substring(start, end);
  // Clean non-printable chars
  console.log(chunk.replace(/[\x00-\x08\x0e-\x1f]/g, '|'));
}
"
